/**
 * CINEMORA — shared domain types.
 *
 * The catalogue is generated by `scripts/build_catalogue.py` into
 * `data/movies.json`; these types describe that exact shape.
 *
 * CINEMORA now carries both films and web series, mirroring an aggregator
 * catalogue: titles carry TMDB-style metadata and each title exposes either
 * native video sources or an iframe-embedded third-party player (the
 * NetMirror model: metadata here, playback delegated to an external player).
 */

/* -------------------------------------------------------------------------- */
/*  Media                                                                      */
/* -------------------------------------------------------------------------- */

export type Quality = "1080p" | "720p" | "480p" | "360p" | "auto";

export interface VideoSource {
  /** Absolute, publicly reachable media URL. */
  url: string;
  mimeType: string;
  quality?: Quality;
  codec?: string;
  label?: string;
  width?: number;
  height?: number;
  /**
   * When present, the player renders an iframe to this URL instead of a native
   * `<video>` element. This is the NetMirror-style aggregation path: the title's
   * metadata lives in CINEMORA while playback is delegated to an external
   * third-party player (which may itself require a browser extension, CORS
   * bypass or DRM handling).
   */
  embedUrl?: string;
  /** Human-readable label for an embedded player, e.g. "Server 1" / "HD". */
  embedLabel?: string;
}

export interface SubtitleSource {
  /** Same-origin URL (proxied through /api/subtitles) or a direct asset. */
  url: string;
  /** ISO 639-1 language tag. */
  language: string;
  label: string;
  kind: "subtitles" | "captions";
  default: boolean;
  format: "vtt" | "srt";
}

export interface ImageAsset {
  /** Path served from `public/` (e.g. `/posters/nosferatu-1922-md.webp`). */
  src: string;
  width: number;
  height: number;
  /** Tiny base64 WebP used as a blur-up placeholder. */
  blurDataURL?: string;
}

/* -------------------------------------------------------------------------- */
/*  Rights                                                                     */
/* -------------------------------------------------------------------------- */

export type VerificationStatus = "pending" | "verified" | "rejected";

export type AssetType = "video" | "poster" | "backdrop" | "subtitle";

export interface AssetRights {
  assetType: AssetType;
  status: VerificationStatus;
  /** Human-readable licence, e.g. "Public domain (US)". */
  license: string;
  /** Where the asset came from, e.g. "Internet Archive". */
  source: string;
  sourceUrl: string;
  licenseUrl?: string;
  /** ISO 3166-1 alpha-2 codes that were explicitly verified. Empty = unknown. */
  verifiedTerritories: string[];
  evidenceUrl?: string;
  verificationNotes?: string;
  verifiedAt?: string;
  verifiedBy?: string;
}

export interface MovieRightsSummary {
  /** `verified` only when every required asset is verified for at least one territory. */
  overallStatus: VerificationStatus;
  assetRights: AssetRights[];
}

/* -------------------------------------------------------------------------- */
/*  Common                                                                     */
/* -------------------------------------------------------------------------- */

export type TitleType = "movie" | "series";

export interface Genre {
  id: string;
  name: string;
  slug: string;
  description?: string;
}

export interface CastMember {
  name: string;
  role: string;
}

/* -------------------------------------------------------------------------- */
/*  Movie                                                                      */
/* -------------------------------------------------------------------------- */

export interface Movie {
  type: "movie";
  id: string;
  /** URL-safe identifier used for every route and storage key. */
  slug: string;
  title: string;
  originalTitle?: string;
  year: number;
  runtimeMinutes: number;
  genres: Genre[];
  synopsis: string;
  tagline?: string;

  poster: ImageAsset;
  backdrop: ImageAsset;
  videoSources: VideoSource[];
  subtitleSources: SubtitleSource[];

  director: string[];
  cast: CastMember[];
  writer?: string[];
  composer?: string[];

  rights: MovieRightsSummary;

  language: string;
  country: string;
  color: "color" | "bw" | "tinted";
  aspectRatio: string;

  /** Canonical archive.org item page — used for attribution links. */
  sourcePage: string;

  /** Editorial weight used for ordering the catalogue. */
  featuredRank?: number;

  createdAt: string;
  updatedAt: string;
}

/* -------------------------------------------------------------------------- */
/*  TV Series                                                                  */
/* -------------------------------------------------------------------------- */

export interface Episode {
  type: "episode";
  id: string;
  /** URL-safe identifier used for every route and storage key. */
  slug: string;
  title: string;
  seasonNumber: number;
  episodeNumber: number;
  runtimeMinutes?: number;
  synopsis?: string;
  tagline?: string;
  airDate?: string;

  poster?: ImageAsset;
  videoSources: VideoSource[];
  subtitleSources: SubtitleSource[];

  director?: string[];
  cast?: CastMember[];

  rights: MovieRightsSummary;

  language?: string;
  country?: string;
  color?: "color" | "bw" | "tinted";
  aspectRatio?: string;

  /** Canonical source page — used for attribution links. */
  sourcePage?: string;

  /** Editorial weight used for ordering the catalogue. */
  featuredRank?: number;

  createdAt: string;
  updatedAt: string;
}

export interface Season {
  id: string;
  slug: string;
  title: string;
  seasonNumber: number;
  poster?: ImageAsset;
  overview?: string;
  airDate?: string;
  episodeCount: number;
  episodes: Episode[];
}

export interface TVSeries {
  type: "series";
  id: string;
  /** URL-safe identifier used for every route and storage key. */
  slug: string;
  title: string;
  originalTitle?: string;
  year: number;
  genres: Genre[];
  synopsis: string;
  tagline?: string;

  poster: ImageAsset;
  backdrop: ImageAsset;

  /** Aggregate episode count across all seasons. */
  totalEpisodes: number;
  /** Number of seasons. */
  seasonCount: number;
  seasons: Season[];

  firstAirDate?: string;
  lastAirDate?: string;
  status?: "returning" | "ended" | "upcoming";

  director?: string[];
  cast?: CastMember[];
  writer?: string[];
  composer?: string[];

  rights: MovieRightsSummary;

  language: string;
  country: string;
  color: "color" | "bw" | "tinted";
  aspectRatio: string;

  /** Canonical source page — used for attribution links. */
  sourcePage: string;

  /** Editorial weight used for ordering the catalogue. */
  featuredRank?: number;

  createdAt: string;
  updatedAt: string;
}

/* -------------------------------------------------------------------------- */
/*  Unions                                                                     */
/* -------------------------------------------------------------------------- */

/** Any browsable title in the catalogue: a film or a web series. */
export type Title = Movie | TVSeries;

/** Anything that can be played: a film or a single episode. */
export type Watchable = Movie | Episode;

export function isMovie(title: Title): title is Movie {
  return title.type === "movie";
}

export function isSeries(title: Title): title is TVSeries {
  return title.type === "series";
}

export function isEpisode(watchable: Watchable): watchable is Episode {
  return watchable.type === "episode";
}

export interface Catalogue {
  generatedAt: string;
  movies: Movie[];
  series: TVSeries[];
}

/* -------------------------------------------------------------------------- */
/*  Client state                                                               */
/* -------------------------------------------------------------------------- */

export interface WatchlistItem {
  titleSlug: string;
  titleType: TitleType;
  addedAt: string;
}

export interface PlaybackProgress {
  titleSlug: string;
  titleType: TitleType;
  currentTime: number;
  duration: number;
  /** True once >= 90% of the runtime has been watched. */
  completed: boolean;
  lastWatchedAt: string;
  playbackRate: number;
}

export interface TerritorySelection {
  code: string;
  source: "heuristic" | "manual";
}
